#!/bin/sh
# Stage + build the freestanding Gambit unikernel example (jolt-microvm).
#
# The hand-written platform files (kmain.c, bare_*.c, entry.S, idt.*, shim.h,
# booter.c, Makefile) live here. The Gambit runtime C and headers are STAGED
# from a full gsc build tree: they are generated by Gambit's configure/make and
# are too large and derivative to vendor.
#
# Three boots, one platform:
#   probe  (default) — a 2-line Scheme program (kernel-probe.scm), the minimal
#                       BOOT-OK green light.
#   full             — the jolt kernel boot + seed image (unikernel-main.scm in
#                       jolt-lang/host/gambit, repl profile: kernel + core +
#                       compiler, no regex): BOOT-OK + jolt-compile-eval smoke.
#   serve            — the jolt nREPL unikernel: boot-probe.scm (full profile,
#                       live compiler) + serve.scm (COM1 bencode nREPL endpoint).
#                       Preamble SERVE/READY lines, then pure bencode; drive it
#                       with ./nrepl-test.py.
#
# Usage:
#   ./stage.sh [path/to/gambit-full-build-tree] [boot] [probe|full|serve]
#       no args      -> stage + make (produces jolt-bare.elf)
#       boot         -> also build booter.c against libkrun and boot the ELF
#       serve        -> build the nREPL endpoint instead of the probe
#
# Env:
#   GSC       path to gsc          (default ~/.local/bin/gsc)
#   LIBKRUN   libkrun prefix       (default /tmp/libkrun)
#   JOBS      make parallelism     (default 18)
#   JOLT_LANG jolt-lang repo       (default ../../../../jolt-lang)
#   CC/BOOT_CC C compiler          (default clang; the 100MB boot.c needs it)
set -eu
cd "$(dirname "$0")"

GSC="${GSC:-$HOME/.local/bin/gsc}"
LIBKRUN="${LIBKRUN:-/tmp/libkrun}"
JOBS="${JOBS:-18}"
GAMBIT_FULL="/tmp/gambit-full"
JOLT_LANG="${JOLT_LANG:-$(cd ../../../../jolt-lang && pwd)}"
HERE="$(pwd)"
DO_BOOT=
MODE=probe
for a in "$@"; do
  case "$a" in
    boot)           DO_BOOT=1 ;;
    probe|full|serve) MODE="$a" ;;
    *)              GAMBIT_FULL="$a" ;;
  esac
done

# --- 1. Scheme -> C + linkfile ------------------------------------------
mkdir -p src
case "$MODE" in
  serve)
    # The nREPL endpoint: boot-probe.scm supplies the full-profile boot with a
    # live jolt-compile-eval; serve.scm adds the bencode read/eval loop. Linking
    # boot-probe.c serve.c emits serve_.c — the linkfile whose ___LNK_serve__
    # entry kmain passes to ___setup.
    ( cd "$JOLT_LANG/host/gambit"
      "$GSC" -target C -c boot-probe.scm
      "$GSC" -target C -c serve.scm
      "$GSC" -link boot-probe.c serve.c
      cp boot-probe.c "$HERE/src/boot.c"
      cp serve.c      "$HERE/src/serve.c"
      cp serve_.c     "$HERE/src/boot_.c"
    )
    BOOT_LINKER=___LNK_serve__
    ;;
  full)
    # the full boot compiles in jolt-lang/host/gambit, where the ##include
    # paths of boot-repl.ss (../chez/..., seed/...) resolve.
    ( cd "$JOLT_LANG/host/gambit"
      "$GSC" -target C -c unikernel-main.scm
      "$GSC" -link unikernel-main.c
      cp unikernel-main.c  "$HERE/src/boot.c"
      cp unikernel-main_.c "$HERE/src/boot_.c"
    )
    BOOT_LINKER=___LNK_unikernel_2d_main__
    ;;
  probe)
    "$GSC" -target C -c kernel-probe.scm
    "$GSC" -link kernel-probe.c
    cp kernel-probe.c  src/boot.c
    cp kernel-probe_.c src/boot_.c
    BOOT_LINKER=___LNK_kernel_2d_probe__
    ;;
esac

# --- 2. stage the Gambit runtime (generated C + headers) ---------------
CORE="_kernel _io _num _std _nonstd _eval _repl _thread _system _module _gambit mem c_intf setup os_base os_setup os_thread os_shell os_io os_tty os_files os_time os_dyn actlog"
mkdir -p include
for f in $CORE; do
  cp "$GAMBIT_FULL/lib/$f.c" src/
done
cp "$GAMBIT_FULL"/lib/*.h    include/
cp "$GAMBIT_FULL"/include/*.h include/

# --- 3. build the ELF ---------------------------------------------------
# clang is required for the generated ~100MB boot.c (gcc explodes: 1h+/17GB).
CC="${CC:-clang}" BOOT_CC="${BOOT_CC:-clang}" \
  make -j"$JOBS" BOOT_LINKER="$BOOT_LINKER"

echo
echo "built: $PWD/jolt-bare.elf (mode=$MODE)"

# --- 4. boot (optional) --------------------------------------------------
if [ -n "$DO_BOOT" ]; then
  clang -O2 -I"$LIBKRUN/include" -o booter booter.c \
    -L"$LIBKRUN/target/release" -lkrun -lkrun_init \
    -Wl,-rpath,"$LIBKRUN/target/release"
  echo "booting: $PWD/jolt-bare.elf (host timeout 30s ends the boot)"
  sudo -u jm --preserve-env timeout 30 ./booter ./jolt-bare.elf
fi
